WITH exploded AS (SELECT id, plan, currency, EXPLODE_OUTER(tier_limits) AS val FROM price_tiers), filtered AS (SELECT *, ROUND(val * 100, 2) AS val_adjusted FROM exploded WHERE val != 69), scored AS (SELECT id, plan, val, COUNT(val_adjusted) OVER w_grp AS currency_count_val_adjusted, MIN(val) OVER (PARTITION BY currency, plan) AS currency_min_val, DENSE_RANK() OVER (ORDER BY val_adjusted DESC NULLS LAST) AS val_adjusted_dense_rank, RANK() OVER (ORDER BY val NULLS FIRST) AS val_rank FROM filtered WINDOW w_grp AS (PARTITION BY currency)), filtered_price_tiers AS (SELECT id, plan, currency_count_val_adjusted, currency_min_val, val_adjusted_dense_rank, val_rank, CAST(val_adjusted_dense_rank AS DOUBLE) AS val_adjusted_dense_rank_str FROM scored WHERE currency_min_val = 67), filtered_price_tiers_2 AS (SELECT id, currency_min_val, val_adjusted_dense_rank, val_rank, val_adjusted_dense_rank_str, CASE WHEN val_rank >= 9 THEN 'High' WHEN val_rank >= 4 THEN 'Medium' ELSE 'Low' END AS val_rank_level FROM filtered_price_tiers WHERE val_adjusted_dense_rank_str IS NOT NULL), metrics AS (SELECT id, val_adjusted_dense_rank, val_adjusted_dense_rank_str, val_rank_level, PERCENT_RANK() OVER w_recent AS currency_min_val_percent_rank, CUME_DIST() OVER w_grp AS val_adjusted_dense_rank_str_cume_dist, PERCENT_RANK() OVER (ORDER BY val_rank DESC) AS val_rank_percent_rank FROM filtered_price_tiers_2 WINDOW w_recent AS (ORDER BY currency_min_val NULLS LAST), w_grp AS (ORDER BY val_adjusted_dense_rank_str DESC)) SELECT CASE WHEN currency_min_val_percent_rank >= 0.72 THEN 'HIGH' ELSE 'LOW' END AS currency_min_val_percent_rank_tier, CASE WHEN val_adjusted_dense_rank_str_cume_dist >= 0.83 THEN 'HIGH' ELSE 'LOW' END AS val_adjusted_dense_rank_str_cume_dist_tier, PERCENTILE_APPROX(val_rank_percent_rank, 0.5) AS val_rank_percent_rank_p50, APPROX_PERCENTILE(val_adjusted_dense_rank_str_cume_dist, 0.95) AS val_adjusted_dense_rank_str_cume_dist_p95, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(currency_min_val_percent_rank), 2) AS avg_currency_min_val_percent_rank, COUNT(*) AS cnt, SUM(val_adjusted_dense_rank) AS total_val_adjusted_dense_rank, GROUPING_ID() AS grouping_id FROM metrics GROUP BY GROUPING SETS ((CASE WHEN currency_min_val_percent_rank >= 0.72 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN val_adjusted_dense_rank_str_cume_dist >= 0.83 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN currency_min_val_percent_rank >= 0.72 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY val_adjusted_dense_rank_str_cume_dist_p95 DESC
